.raizsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2c3a33;
    background: linear-gradient(160deg, #f4f8f3 0%, #eaf3ec 55%, #fdf7ee 100%);
    border-radius: 18px;
}

.raizsim-container * {
    box-sizing: border-box;
}

.raizsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0f7a5a 0%, #1aa179 55%, #d98a3d 130%);
    color: #f4fdf8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 30px rgba(15, 122, 90, 0.28);
}

.raizsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.raizsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #fff4e3;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.raizsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ecfbf3;
}

.raizsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4d6358;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.raizsim-period-counter #currentDay,
.raizsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f7a5a;
}

.raizsim-round-name {
    background: rgba(26, 161, 121, 0.14);
    color: #0f7a5a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.raizsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b35a14;
    background: rgba(217, 138, 61, 0.16);
    border: 1px solid rgba(217, 138, 61, 0.36);
    padding: 4px 12px;
    border-radius: 999px;
}

.raizsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.raizsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dcebe2;
    box-shadow: 0 6px 16px rgba(20, 80, 60, 0.08);
    border-top: 4px solid #1aa179;
}

.raizsim-card-viability { border-top-color: #1aa179; }
.raizsim-card-access { border-top-color: #2f8fd0; }
.raizsim-card-esg { border-top-color: #8a63c8; }
.raizsim-card-risk { border-top-color: #d9663d; }

.raizsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6e8579;
}

.raizsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #233a31;
    font-variant-numeric: tabular-nums;
}

.raizsim-card-viability .raizsim-value { color: #0f7a5a; }
.raizsim-card-access .raizsim-value { color: #2f8fd0; }
.raizsim-card-esg .raizsim-value { color: #7a4fc0; }
.raizsim-card-risk .raizsim-value { color: #d9663d; }

.raizsim-sublabel {
    font-size: 0.76rem;
    color: #7e948a;
    line-height: 1.35;
}

.raizsim-viab-negative .raizsim-value { color: #d6402e; }
.raizsim-viab-positive .raizsim-value { color: #0f9d6e; }

.raizsim-risk-high { border-top-color: #d6402e; }
.raizsim-risk-high .raizsim-value { color: #d6402e; }
.raizsim-risk-low { border-top-color: #1aa179; }
.raizsim-risk-low .raizsim-value { color: #0f9d6e; }

.raizsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dcebe2;
    color: #3a4d44;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(20, 80, 60, 0.06);
}

.raizsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #0f7a5a;
}

.raizsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1aa179;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 80, 60, 0.08);
}

.raizsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.raizsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1d4d3c;
    margin-bottom: 6px;
}

.raizsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #41584d;
}

.raizsim-briefing-text strong { color: #0f7a5a; }
.raizsim-briefing-text em { color: #b35a14; font-style: italic; }

.raizsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dcebe2;
    box-shadow: 0 6px 16px rgba(20, 80, 60, 0.08);
}

.raizsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1d4d3c;
    border-bottom: 2px solid #e3efe7;
    padding-bottom: 8px;
}

.raizsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #34473e;
    margin: 14px 0 6px;
}

.raizsim-container select,
.raizsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c3dccd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #233a31;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.raizsim-container select:focus,
.raizsim-container input[type="number"]:focus {
    outline: none;
    border-color: #1aa179;
    box-shadow: 0 0 0 3px rgba(26, 161, 121, 0.18);
}

.raizsim-container select option {
    background-color: #ffffff;
    color: #233a31;
}

.raizsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1aa179;
}

.raizsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5d7468;
    margin-top: 4px;
}

.raizsim-range-readout span:last-child {
    color: #0f7a5a;
    font-weight: 800;
}

.raizsim-hint {
    font-size: 0.8rem;
    color: #7e948a;
    margin-top: 4px;
    line-height: 1.4;
}

.raizsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.raizsim-container .btn-primary {
    background: linear-gradient(135deg, #0f7a5a 0%, #1aa179 100%);
    border: none;
    color: #f4fdf8;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(15, 122, 90, 0.32);
}

.raizsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.raizsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c3dccd;
    color: #5d7468;
    background: transparent;
}

.raizsim-coach {
    background: linear-gradient(160deg, #1d4d3c 0%, #16604a 100%);
    color: #e9f7f0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(15, 60, 45, 0.25);
}

.raizsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7fe3bd;
    margin-bottom: 8px;
}

.raizsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.raizsim-coach-body strong { color: #9fefce; }
.raizsim-coach-body em { color: #ffcf94; font-style: italic; }

.raizsim-history,
.raizsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dcebe2;
    box-shadow: 0 6px 16px rgba(20, 80, 60, 0.08);
}

.raizsim-history h3,
.raizsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1d4d3c;
}

.raizsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4d44;
}

.raizsim-container table#usfHistoryTable th {
    background: #eef6f0;
    color: #0f7a5a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6db;
}

.raizsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e6f0ea;
    color: #41584d;
}

.raizsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6faf7;
}

.raizsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .raizsim-container {
        padding: 14px;
    }
    .raizsim-header h1 {
        font-size: 1.7rem;
    }
    .raizsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .raizsim-value {
        font-size: 2rem;
    }
    .raizsim-clock {
        margin-left: 0;
    }
    .raizsim-period-counter {
        font-size: 0.88rem;
    }
    .raizsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .raizsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================
   v1.1.0 — Completion debrief (append-only, scoped .raiz-cm)
   Palette: green #0f7a5a · teal #1aa179 · dark #1d4d3c · red #d6402e
   ============================================================ */
.raiz-cm { font-family: inherit; color: #1d4d3c; text-align: left; }
.raiz-cm-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
    border-bottom: 3px solid #1aa179; padding-bottom: 14px; margin-bottom: 16px; }
.raiz-cm-scorebox { display: flex; flex-direction: column; align-items: center;
    background: #0f7a5a; color: #fff; border-radius: 12px; padding: 12px 20px; min-width: 130px; }
.raiz-cm-score { font-size: 2.6rem; line-height: 1; font-weight: 800; }
.raiz-cm-score-max { font-size: 1rem; font-weight: 600; opacity: 0.8; margin-left: 2px; }
.raiz-cm-score-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; opacity: 0.85; margin-top: 4px; }
.raiz-cm-tier { font-size: 1.5rem; font-weight: 700; color: #1d4d3c; flex: 1 1 auto; }
.raiz-cm-chips { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 16px; }
.raiz-cm-chip { flex: 1 1 190px; display: flex; align-items: center; gap: 8px;
    background: #f4fdf8; border: 1px solid #dcebe2; border-left: 5px solid #7a938a; border-radius: 8px; padding: 9px 12px; }
.raiz-cm-chip.is-met { border-left-color: #1aa179; }
.raiz-cm-chip.is-missed { border-left-color: #d6402e; }
.raiz-cm-chip-l { font-weight: 600; color: #233a31; font-size: 0.88rem; }
.raiz-cm-badge { margin-left: auto; font-size: 0.68rem; font-weight: 700; text-transform: uppercase;
    letter-spacing: 0.04em; padding: 3px 8px; border-radius: 999px; color: #fff; }
.raiz-cm-badge.is-met { background: #1aa179; }
.raiz-cm-badge.is-missed { background: #d6402e; }
.raiz-cm-kpis { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.raiz-cm-kpi { flex: 1 1 110px; text-align: center; background: #fff; border: 1px solid #dcebe2;
    border-top: 3px solid #0f7a5a; border-radius: 8px; padding: 10px 8px; }
.raiz-cm-kpi-v { font-size: 1.3rem; font-weight: 800; color: #0f7a5a; font-variant-numeric: tabular-nums; }
.raiz-cm-kpi-l { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.04em; color: #5a736a; margin-top: 3px; }
.raiz-cm-insights-title { font-weight: 700; color: #1d4d3c; margin-bottom: 6px; }
.raiz-cm-insights ul { margin: 0; padding-left: 20px; }
.raiz-cm-insights li { margin-bottom: 7px; line-height: 1.5; }

