(function() {
    'use strict';

    class RaizAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Base-of-Pyramid Health`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Clínicas Raíz S.A.).
            this.EBITDA = 0.86;              // GTQ 0.86M EBITDA line (6% of GTQ 14.4M)
            this.TRANCHE = 4.0;             // GTQ 4.0M frozen growth tranche
            this.FEE_UP_MARGIN = 0.9;       // +GTQ 5 fee lifts margin ~GTQ 0.9M
            this.ACCREDIT_COST = 0.25;      // ~GTQ 250K third-party accreditation
            this.CODE_COST = 0.04;          // ~GTQ 40K self-regulation code
            this.BLENDED_UNLOCK = 6.0;      // up to GTQ 6M blended co-financing, rating-gated

            // Concept truths.
            this.TRUE_LENS = `quintile`;
            this.TRUE_CONSTRAINT = `affordability`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    viability: 0,            // GTQ M annual EBITDA impact vs status quo
                    access: 52,              // access index (0.52 -> 52 on a 0–100 scale)
                    esg: 30,                 // external ESG / social rating (0–100)
                    gateRisk: 55,            // runway / trust / closure risk (lower better)
                    budgetUsed: 0,           // GTQ M of the growth tranche committed
                    pricedOut: false,        // raised fees without modelling who drops out
                    permanentSubsidy: false, // underpriced into non-declining subsidy
                    noCert: false,           // skipped certification
                    noAvailability: false,   // no community-promoter availability strategy
                    viabHistory: [0],
                    accessHistory: [52],
                    esgHistory: [30],
                    riskHistory: [55],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a click-through must not auto-win.
                state.decisions = {
                    lens: `average`,
                    constraint: `quality`,
                    rigor: 40,
                    bundle: `core`,
                    availability: 20,
                    pharmacy: `profit`,
                    cert: `none`,
                    fee: `up`,
                    subsidy: 20,
                    scorecard: `glowing`,
                    subsidyPath: `flat`,
                    esgRole: `trailing`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ln = document.getElementById(`lensInput`);
                const cn = document.getElementById(`constraintInput`);
                const rg = document.getElementById(`rigorInput`);
                if (ln) decisions.lens = ln.value;
                if (cn) decisions.constraint = cn.value;
                if (rg) decisions.rigor = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const bd = document.getElementById(`bundleInput`);
                const av = document.getElementById(`availabilityInput`);
                const ph = document.getElementById(`pharmacyInput`);
                if (bd) decisions.bundle = bd.value;
                if (av) decisions.availability = parseInt(av.value, 10);
                if (ph) decisions.pharmacy = ph.value;
                if (!Number.isFinite(decisions.availability) || decisions.availability < 0 || decisions.availability > 100) {
                    warn(`warn_availability_range`); return false;
                }
            } else if (round === 3) {
                const ct = document.getElementById(`certInput`);
                const fe = document.getElementById(`feeInput`);
                const sb = document.getElementById(`subsidyInput`);
                if (ct) decisions.cert = ct.value;
                if (fe) decisions.fee = fe.value;
                if (sb) decisions.subsidy = parseInt(sb.value, 10);
                if (!Number.isFinite(decisions.subsidy) || decisions.subsidy < 0 || decisions.subsidy > 100) {
                    warn(`warn_subsidy_range`); return false;
                }
            } else if (round === 4) {
                const sc = document.getElementById(`scorecardInput`);
                const sp = document.getElementById(`subsidyPathInput`);
                const er = document.getElementById(`esgRoleInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sc) decisions.scorecard = sc.value;
                if (sp) decisions.subsidyPath = sp.value;
                if (er) decisions.esgRole = er.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let viabDelta = 0, accessDelta = 0, esgDelta = 0, riskDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the affordability map (read who you actually serve).
                switch (d.lens) {
                    case `quintile`: accessDelta += 8; esgDelta += 6; riskDelta -= 6; coachKey = `coach_r1_quintile`; break;
                    case `average`: accessDelta -= 4; riskDelta += 5; coachKey = `coach_r1_average`; break;
                    case `payers`: accessDelta -= 8; esgDelta -= 4; riskDelta += 6; coachKey = `coach_r1_payers`; break;
                    case `volume`: accessDelta -= 3; esgDelta -= 2; riskDelta += 4; coachKey = `coach_r1_volume`; break;
                }

                // Name the binding constraint (price as the access lever).
                switch (d.constraint) {
                    case `affordability`: accessDelta += 6; esgDelta += 4; riskDelta -= 5; if (d.lens === `quintile`) coachKey = `coach_r1_sharp`; break;
                    case `quality`: riskDelta += 4; break;
                    case `awareness`: accessDelta -= 2; riskDelta += 4; break;
                    case `capacity`: riskDelta += 3; break;
                }

                if (d.rigor >= 60) { accessDelta += 5; esgDelta += 3; riskDelta -= 4; }
                else if (d.rigor <= 25) { accessDelta -= 4; riskDelta += 5; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.lens === `quintile` && d.constraint === `affordability`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design the offer — depth, availability and the pharmacy.
                switch (d.bundle) {
                    case `tiered`: accessDelta += 7; esgDelta += 5; viabDelta += 0.1; coachKey = `coach_r2_tiered`; break;
                    case `core`: viabDelta += 0.2; accessDelta -= 2; coachKey = `coach_r2_core`; break;
                    case `broad`: viabDelta -= 0.5; accessDelta += 4; riskDelta += 5; coachKey = `coach_r2_broad`; break;
                }

                // Availability via community promoters (Common Error 5: no reach for remote patients).
                const av = d.availability / 100;
                accessDelta += av * 14;                          // promoters reach the half who live far
                viabDelta -= av * 0.4;                           // but cost to train and supervise
                if (d.availability <= 10) {
                    ds.noAvailability = true;
                    accessDelta -= 8; esgDelta -= 4; riskDelta += 6;
                    coachKey = `coach_r2_noavail`;
                } else if (d.availability >= 40) {
                    esgDelta += 4; riskDelta -= 3;
                }

                // Generics-pharmacy strategy.
                switch (d.pharmacy) {
                    case `integrated`: accessDelta += 4; viabDelta += 0.15; esgDelta += 3; break;
                    case `profit`: viabDelta += 0.3; accessDelta -= 5; esgDelta -= 3; if (coachKey === `coach_default` || coachKey === `coach_r2_core`) coachKey = `coach_r2_pharmprofit`; break;
                    case `drop`: accessDelta -= 6; viabDelta -= 0.1; esgDelta -= 2; break;
                }

                summaryKey = (d.bundle === `tiered` && d.availability >= 40 && d.pharmacy === `integrated`) ? `sum_r2_good` :
                             (ds.noAvailability ? `sum_r2_noavail` : `sum_r2_weak`);
            } else if (round === 3) {
                // The decisive round: certification + pricing-access tradeoff.
                switch (d.cert) {
                    case `accredit`: spend += this.ACCREDIT_COST; esgDelta += 16; riskDelta -= 12; accessDelta += 2; coachKey = `coach_r3_accredit`; break;
                    case `code`: spend += this.CODE_COST; esgDelta += 6; riskDelta -= 4; coachKey = `coach_r3_code`; break;
                    case `none`: ds.noCert = true; esgDelta -= 8; riskDelta += 12; coachKey = `coach_r3_nocert`; break;
                }

                // Pricing-access fork (Common Errors 1 & 2). Cross-subsidy softens the access hit.
                const sub = d.subsidy / 100;
                if (d.fee === `up`) {
                    // +GTQ 5 lifts margin ~GTQ 0.9M but prices out 6,000 of the poorest visits.
                    viabDelta += this.FEE_UP_MARGIN;
                    const accessHit = 26 * (1 - sub * 0.6);       // subsidy buys back some of the dropouts
                    accessDelta -= accessHit;
                    esgDelta -= 7 * (1 - sub * 0.5);
                    if (sub < 0.3) { ds.pricedOut = true; riskDelta += 8; coachKey = `coach_r3_priceout`; }
                } else if (d.fee === `hold`) {
                    // No margin gain, no extra dropouts.
                    if (coachKey === `coach_default`) coachKey = `coach_r3_hold`;
                } else { // down + membership
                    // Reach expands but volume/staffing is the constraint — deep deficit without enough cross-subsidy.
                    accessDelta += 12;
                    viabDelta += sub * 0.8 - 1.1;                 // membership/cross-subsidy partly funds the cut
                    esgDelta += 4;
                    if (sub < 0.4) { ds.permanentSubsidy = true; coachKey = `coach_r3_underprice`; }
                }

                // Cross-subsidy mix widens access without burning the tranche.
                accessDelta += sub * 6;
                if (d.subsidy >= 30 && d.subsidy <= 70) { esgDelta += 3; riskDelta -= 2; }

                summaryKey = (d.cert === `accredit` && d.fee !== `up` && d.subsidy >= 30) ? `sum_r3_good` :
                             (ds.pricedOut ? `sum_r3_priceout` :
                             (ds.permanentSubsidy ? `sum_r3_underprice` :
                             (ds.noCert ? `sum_r3_nocert` : `sum_r3_weak`)));
            } else if (round === 4) {
                // The viability gate pitch & 18-month recovery.
                switch (d.scorecard) {
                    case `honest`: esgDelta += 10; riskDelta -= 10; coachKey = `coach_r4_honest`; break;
                    case `glowing`: esgDelta -= 10; riskDelta += 18; coachKey = `coach_r4_glowing`; break;
                    case `minimal`: esgDelta -= 4; riskDelta += 6; coachKey = `coach_r4_minimal`; break;
                }

                // 18-month subsidy path — does subsidy decline toward break-even?
                switch (d.subsidyPath) {
                    case `declining`: viabDelta += 0.5; esgDelta += 6; riskDelta -= 8; break;
                    case `flat`: riskDelta += 5; coachKey = (coachKey === `coach_r4_glowing`) ? coachKey : `coach_r4_flatsub`; break;
                    case `rising`: viabDelta -= 0.6; riskDelta += 10; ds.permanentSubsidy = true; coachKey = `coach_r4_risingsub`; break;
                }

                // The ESG rating as a strategic financing asset (Common Error 4).
                switch (d.esgRole) {
                    case `driver`: esgDelta += 10; riskDelta -= 8; if (ds.esg + esgDelta >= 60) viabDelta += 0.4; coachKey = (d.scorecard === `honest`) ? `coach_r4_gatewon` : coachKey; break;
                    case `trailing`: esgDelta -= 6; riskDelta += 6; break;
                    case `paperwork`: esgDelta -= 14; riskDelta += 12; coachKey = `coach_r4_paperwork`; break;
                }

                if (d.conviction >= 60) { esgDelta += 4; riskDelta -= 4; }
                else if (d.conviction <= 25) { esgDelta -= 4; riskDelta += 5; }

                summaryKey = (d.scorecard === `honest` && d.subsidyPath === `declining` && d.esgRole === `driver`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the GTQ 4.0M growth tranche.
            ds.budgetUsed = Math.min(this.TRANCHE, Math.round((ds.budgetUsed + spend) * 100) / 100);

            // Apply deltas. Viability is GTQ M (can go negative); the indices are 0–100.
            ds.viability = Math.round((ds.viability + viabDelta) * 100) / 100;
            ds.access = Math.max(0, Math.min(100, Math.round(ds.access + accessDelta)));
            ds.esg = Math.max(0, Math.min(100, Math.round(ds.esg + esgDelta)));
            ds.gateRisk = Math.max(0, Math.min(100, Math.round(ds.gateRisk + riskDelta)));

            ds.viabHistory.push(ds.viability);
            ds.accessHistory.push(ds.access);
            ds.esgHistory.push(ds.esg);
            ds.riskHistory.push(ds.gateRisk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite where results_utils.php reads it (per-period + final).
            const _score = this._composite(ds);
            ds.score = _score;
            if (!ds.performance || typeof ds.performance !== `object`) { ds.performance = {}; }
            ds.performance.overallScore = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                viability: ds.viability,
                viabDelta: Math.round(viabDelta * 100) / 100,
                access: ds.access,
                accessDelta: Math.round(accessDelta),
                esg: ds.esg,
                esgDelta: Math.round(esgDelta),
                gateRisk: ds.gateRisk,
                riskDelta: Math.round(riskDelta),
                budgetUsed: ds.budgetUsed,
                pricedOut: ds.pricedOut,
                permanentSubsidy: ds.permanentSubsidy,
                noCert: ds.noCert,
                noAvailability: ds.noAvailability,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Guatemalan Quetzal: "Q1.20M" in English, "1,20 M Q" in Spanish (comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(2).replace(`.`, `,`)} M Q`;
            }
            return `${sign}Q${abs.toFixed(2)}M`;
        }

