        _composite(ds) {
            // v1.1.0: verbatim v1.0.0 formula, extracted so calculateResults can persist it every period.
            const viability = ds.viability;
            const access = Math.round(ds.access);
            const esg = Math.round(ds.esg);
            const gateRisk = Math.round(ds.gateRisk);
            const viabScore = Math.max(-25, Math.min(25, viability * 12));
            return Math.round(access * 0.30 + esg * 0.30 + (100 - gateRisk) * 0.24 + (viabScore + 25) * 0.32);
        }

        formatCompletionMessage(summary) {
            // v1.1.0: localized debrief; without this override the engine discards score/tier/insights.
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            if (!summary || typeof summary.composite === `undefined`) {
                return `<div class="raiz-cm"><div class="raiz-cm-tier">${t(`grade_missed`)}</div></div>`;
            }
            const tier = summary.performance || t(summary.performanceKey || `grade_missed`);
            const gateLow = summary.gateRisk <= 35;
            const chip = (ok, label) => `<div class="raiz-cm-chip ${ok ? `is-met` : `is-missed`}"><span class="raiz-cm-chip-l">${label}</span><span class="raiz-cm-badge ${ok ? `is-met` : `is-missed`}">${ok ? t(`cm_met`) : t(`cm_missed`)}</span></div>`;
            const lis = (summary.insights || []).map((s) => `<li>${s}</li>`).join(``);
            return `
                <div class="raiz-cm">
                    <div class="raiz-cm-head">
                        <div class="raiz-cm-scorebox">
                            <div class="raiz-cm-score">${summary.composite}<span class="raiz-cm-score-max">/100</span></div>
                            <div class="raiz-cm-score-label">${t(`cm_score_label`)}</div>
                        </div>
                        <div class="raiz-cm-tier">${tier}</div>
                    </div>
                    <div class="raiz-cm-chips">
                        ${chip(summary.solvent, t(`cm_chip_solvent`))}
                        ${chip(summary.reaches, t(`cm_chip_reaches`))}
                        ${chip(summary.rated, t(`cm_chip_rated`))}
                        ${chip(gateLow, t(`cm_chip_gate`))}
                    </div>
                    <div class="raiz-cm-kpis">
                        <div class="raiz-cm-kpi"><div class="raiz-cm-kpi-v">${summary.access}</div><div class="raiz-cm-kpi-l">${t(`cm_kpi_access`)}</div></div>
                        <div class="raiz-cm-kpi"><div class="raiz-cm-kpi-v">${summary.esg}</div><div class="raiz-cm-kpi-l">${t(`cm_kpi_esg`)}</div></div>
                        <div class="raiz-cm-kpi"><div class="raiz-cm-kpi-v">${summary.gateRisk}</div><div class="raiz-cm-kpi-l">${t(`cm_kpi_gate`)}</div></div>
                        <div class="raiz-cm-kpi"><div class="raiz-cm-kpi-v">${this._fmtMoney(Number(summary.viability))}</div><div class="raiz-cm-kpi-l">${t(`cm_kpi_viab`)}</div></div>
                    </div>
                    <div class="raiz-cm-insights">
                        <div class="raiz-cm-insights-title">${t(`cm_insights_title`)}</div>
                        <ul>${lis}</ul>
                    </div>
                </div>
            `;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const viability = ds.viability;
            const access = Math.round(ds.access);
            const esg = Math.round(ds.esg);
            const gateRisk = Math.round(ds.gateRisk);

            // Composite: access, ESG rating, low gate risk, plus a viability bonus
            // (each GTQ M of EBITDA impact worth ~12 points, capped at ±25).
            // v1.1.0: composite via _composite(ds) — single source of truth, value byte-identical to v1.0.0.
            const composite = this._composite(ds);

            const solvent = viability >= 0;
            const reaches = access >= 60;
            const rated = esg >= 60;
            const gateRiskLow = gateRisk <= 35;
            const blendedUnlocked = esg >= 60;
            const collapsed = ds.pricedOut || ds.permanentSubsidy || ds.noCert || ds.noAvailability || gateRisk >= 70;

            // The documented Common Errors dominate the verdict even when a strong play in
            // other rounds masks the headline KPIs — the lesson is that these are gate failures.
            // v1.1.0: tier is now i18n-keyed (was hardcoded English) so it localizes.
            let performanceKey = `grade_missed`;
            if (solvent && reaches && rated && gateRiskLow && composite >= 75 && !collapsed) performanceKey = `grade_cleared`;
            else if (ds.pricedOut) performanceKey = `grade_pricedout`;
            else if (ds.permanentSubsidy || !solvent) performanceKey = `grade_subsidytrap`;
            else if (ds.noCert) performanceKey = `grade_trust`;
            else if (ds.noAvailability) performanceKey = `grade_unreachable`;
            else if (reaches && rated && solvent && gateRiskLow) performanceKey = `grade_tranche`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (solvent && reaches && rated) insights.push(window.mySimulation.t(`insight_cleared`));
            else if (ds.pricedOut) insights.push(window.mySimulation.t(`insight_pricedout`));
            else if (ds.permanentSubsidy) insights.push(window.mySimulation.t(`insight_subsidytrap`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (blendedUnlocked) insights.push(window.mySimulation.t(`insight_blended`));
            else insights.push(window.mySimulation.t(`insight_noblended`));
            if (ds.noCert) insights.push(window.mySimulation.t(`insight_nocert`));
            if (ds.noAvailability) insights.push(window.mySimulation.t(`insight_noavail`));
            if (viability < 0) insights.push(window.mySimulation.t(`insight_deficit`));
            if (reaches && rated && gateRiskLow) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                totalPeriods: history.length,
                viability: viability,
                access: access,
                esg: esg,
                gateRisk: gateRisk,
                solvent: solvent,
                reaches: reaches,
                rated: rated,
                blendedUnlocked: blendedUnlocked,
                composite: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.pricedOut) return window.mySimulation.t(`hint_pricedout`);
            if (ds.noAvailability) return window.mySimulation.t(`hint_noavail`);
            if (ds.permanentSubsidy) return window.mySimulation.t(`hint_subsidy`);
            if (ds.noCert && state.currentPeriod >= 3) return window.mySimulation.t(`hint_nocert`);
            if (ds.gateRisk >= 65) return window.mySimulation.t(`hint_risk`);
            if (state.currentPeriod >= 3 && ds.esg < 45) return window.mySimulation.t(`hint_esg`);
            if (ds.access >= 65 && ds.esg >= 60 && ds.gateRisk <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

